-- ANGELCARE AC WHATSAPP — SOVEREIGN REVENUE INTELLIGENCE OS 2040
-- Canonical additive migration. No destructive DROP/DELETE/TRUNCATE statements.

begin;

create table if not exists public.ac_whatsapp_ri_doctrine_packs (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  description text,
  service_line text not null default 'all',
  customer_type text not null default 'all',
  status text not null default 'draft' check (status in ('draft','validated','active','paused','archived')),
  maturity_level text not null default 'L0' check (maturity_level in ('L0','L1','L2','L3','L4','L5','L6')),
  version integer not null default 1,
  source_kind text not null default 'manual',
  applicability_score numeric(6,2) not null default 0,
  coverage_score numeric(6,2) not null default 0,
  commercial_priority integer not null default 50,
  default_goal text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.ac_whatsapp_ri_doctrine_nodes (
  id uuid primary key default gen_random_uuid(),
  pack_id uuid not null references public.ac_whatsapp_ri_doctrine_packs(id) on delete cascade,
  code text not null,
  title text not null,
  customer_type text not null default 'all',
  service_line text not null default 'all',
  journey_stage text not null default 'all',
  intent_family text not null default 'all',
  trigger_terms text[] not null default '{}',
  trigger_regex text,
  objective text,
  tone_profile jsonb not null default '{}'::jsonb,
  emotional_strategy jsonb not null default '{}'::jsonb,
  commercial_intensity integer not null default 3 check (commercial_intensity between 0 and 6),
  action_type text not null default 'reply' check (action_type in ('reply','suggest','wait','handoff','qualify','close','followup','protect')),
  response_guidance text,
  response_variants jsonb not null default '[]'::jsonb,
  qualification_questions text[] not null default '{}',
  objection_class text,
  proof_options text[] not null default '{}',
  next_actions jsonb not null default '[]'::jsonb,
  escalation_rules jsonb not null default '{}'::jsonb,
  exclusions jsonb not null default '{}'::jsonb,
  forbidden_claims text[] not null default '{}',
  success_signals text[] not null default '{}',
  failure_signals text[] not null default '{}',
  cross_sell jsonb not null default '{}'::jsonb,
  follow_up_rules jsonb not null default '{}'::jsonb,
  priority integer not null default 50,
  maturity_weight numeric(6,4) not null default .25,
  status text not null default 'active' check (status in ('draft','active','paused','archived')),
  source_import_id uuid,
  source_row_number integer,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(pack_id, code)
);

create table if not exists public.ac_whatsapp_ri_engine_settings (
  id uuid primary key default gen_random_uuid(),
  scope_type text not null default 'global' check (scope_type in ('global','account','queue','campaign','service_line')),
  scope_id uuid,
  autonomy_mode text not null default 'manual' check (autonomy_mode in ('manual','assisted','controlled','no_shift','overflow','campaign','full')),
  enabled boolean not null default true,
  min_autonomy_confidence numeric(5,4) not null default .82,
  min_assist_confidence numeric(5,4) not null default .55,
  commercial_intensity_cap integer not null default 5 check (commercial_intensity_cap between 0 and 6),
  after_hours_start time not null default '19:00',
  after_hours_end time not null default '08:00',
  timezone text not null default 'Africa/Casablanca',
  overflow_threshold integer not null default 25,
  pause_on_openwa_failure boolean not null default true,
  metadata jsonb not null default '{}'::jsonb,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists ac_whatsapp_ri_engine_settings_scope_uq on public.ac_whatsapp_ri_engine_settings(scope_type, coalesce(scope_id,'00000000-0000-0000-0000-000000000000'::uuid));

create table if not exists public.ac_whatsapp_ri_imports (
  id uuid primary key default gen_random_uuid(),
  file_name text not null,
  sha256 text not null,
  status text not null default 'processing' check (status in ('processing','validated','review_required','failed','archived')),
  pack_id uuid references public.ac_whatsapp_ri_doctrine_packs(id) on delete set null,
  headers jsonb not null default '[]'::jsonb,
  mapping jsonb not null default '{}'::jsonb,
  stats jsonb not null default '{}'::jsonb,
  uploaded_by uuid,
  processed_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.ac_whatsapp_ri_import_rows (
  id uuid primary key default gen_random_uuid(),
  import_id uuid not null references public.ac_whatsapp_ri_imports(id) on delete cascade,
  row_number integer not null,
  raw_row jsonb not null default '{}'::jsonb,
  normalized_row jsonb not null default '{}'::jsonb,
  status text not null default 'review' check (status in ('applicable','review','blocked','ignored')),
  errors text[] not null default '{}',
  warnings text[] not null default '{}',
  applicability_score numeric(6,2) not null default 0,
  created_at timestamptz not null default now(),
  unique(import_id,row_number)
);

do $$ begin
  if not exists(select 1 from pg_constraint where conname='ac_whatsapp_ri_doctrine_nodes_source_import_fk') then
    alter table public.ac_whatsapp_ri_doctrine_nodes add constraint ac_whatsapp_ri_doctrine_nodes_source_import_fk foreign key (source_import_id) references public.ac_whatsapp_ri_imports(id) on delete set null not valid;
  end if;
end $$;

create table if not exists public.ac_whatsapp_ri_conversation_state (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null unique references public.ac_whatsapp_conversations(id) on delete cascade,
  mode text not null default 'manual' check (mode in ('manual','assist','selected_auto','account_auto','protected')),
  doctrine_pack_id uuid references public.ac_whatsapp_ri_doctrine_packs(id) on delete set null,
  current_goal text,
  journey_stage text not null default 'unknown',
  intent_family text,
  relationship_temperature text,
  momentum text,
  emotional_signals jsonb not null default '{}'::jsonb,
  scores jsonb not null default '{}'::jsonb,
  opportunity jsonb not null default '{}'::jsonb,
  memory jsonb not null default '{}'::jsonb,
  maturity_level text not null default 'L0' check (maturity_level in ('L0','L1','L2','L3','L4','L5','L6')),
  last_decision_id uuid,
  last_automation_at timestamptz,
  takeover_reason text,
  excluded boolean not null default false,
  enabled_by uuid,
  paused_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.ac_whatsapp_ri_relationship_memory (
  id uuid primary key default gen_random_uuid(),
  entity_type text not null check (entity_type in ('contact','organization','household')),
  entity_key text not null,
  contact_id uuid references public.ac_whatsapp_contacts(id) on delete set null,
  organization_name text,
  customer_type text,
  service_lines text[] not null default '{}'::text[],
  memory jsonb not null default '{}'::jsonb,
  opportunity jsonb not null default '{}'::jsonb,
  commitments jsonb not null default '[]'::jsonb,
  objections jsonb not null default '[]'::jsonb,
  last_goal text,
  last_journey_stage text,
  last_intent_family text,
  success_count integer not null default 0,
  failure_count integer not null default 0,
  human_override_count integer not null default 0,
  last_interaction_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(entity_type,entity_key)
);

create table if not exists public.ac_whatsapp_ri_decisions (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.ac_whatsapp_conversations(id) on delete cascade,
  input_message_id uuid references public.ac_whatsapp_messages(id) on delete set null,
  trigger_type text not null default 'inbound_message',
  state_before jsonb not null default '{}'::jsonb,
  doctrine_pack_id uuid references public.ac_whatsapp_ri_doctrine_packs(id) on delete set null,
  doctrine_node_ids uuid[] not null default '{}',
  chosen_action text not null,
  response_text text,
  confidence numeric(6,5) not null default 0,
  commercial_intensity integer not null default 0,
  reasoning jsonb not null default '{}'::jsonb,
  risk jsonb not null default '{}'::jsonb,
  eligibility text not null default 'blue' check (eligibility in ('green','blue','amber','red')),
  status text not null default 'planned' check (status in ('planned','simulated','suggested','handoff','queued','executed','blocked','failed')),
  output_message_id uuid references public.ac_whatsapp_messages(id) on delete set null,
  execution_error text,
  executed_at timestamptz,
  created_at timestamptz not null default now()
);

do $$ begin
  if not exists(select 1 from pg_constraint where conname='ac_whatsapp_ri_conversation_state_last_decision_fk') then
    alter table public.ac_whatsapp_ri_conversation_state add constraint ac_whatsapp_ri_conversation_state_last_decision_fk foreign key (last_decision_id) references public.ac_whatsapp_ri_decisions(id) on delete set null not valid;
  end if;
end $$;

create table if not exists public.ac_whatsapp_ri_learning_events (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.ac_whatsapp_conversations(id) on delete cascade,
  decision_id uuid references public.ac_whatsapp_ri_decisions(id) on delete set null,
  event_type text not null,
  rating numeric(5,2),
  correction text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid,
  created_at timestamptz not null default now()
);

create table if not exists public.ac_whatsapp_ri_maturity (
  id uuid primary key default gen_random_uuid(),
  dimension_type text not null,
  dimension_key text not null,
  samples bigint not null default 0,
  successful_count bigint not null default 0,
  failed_count bigint not null default 0,
  override_count bigint not null default 0,
  conversion_count bigint not null default 0,
  score numeric(6,5) not null default 0,
  maturity_level text not null default 'L0' check (maturity_level in ('L0','L1','L2','L3','L4','L5','L6')),
  evidence jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(dimension_type,dimension_key)
);

create table if not exists public.ac_whatsapp_ri_governance_proposals (
  id uuid primary key default gen_random_uuid(),
  fingerprint text not null unique,
  proposal_type text not null,
  title text not null,
  description text,
  evidence jsonb not null default '{}'::jsonb,
  proposed_change jsonb not null default '{}'::jsonb,
  risk_level text not null default 'medium' check (risk_level in ('low','medium','high','critical')),
  status text not null default 'proposed' check (status in ('proposed','under_review','approved','rejected','implemented')),
  review_notes text,
  reviewed_by uuid,
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.ac_whatsapp_ri_simulations (
  id uuid primary key default gen_random_uuid(),
  pack_id uuid references public.ac_whatsapp_ri_doctrine_packs(id) on delete set null,
  input jsonb not null default '{}'::jsonb,
  output jsonb not null default '{}'::jsonb,
  verdict text not null default 'review',
  created_by uuid,
  created_at timestamptz not null default now()
);

create table if not exists public.ac_whatsapp_ri_runtime_events (
  id uuid primary key default gen_random_uuid(),
  event_type text not null,
  severity text not null default 'info' check (severity in ('info','warning','high','critical')),
  conversation_id uuid references public.ac_whatsapp_conversations(id) on delete set null,
  doctrine_pack_id uuid references public.ac_whatsapp_ri_doctrine_packs(id) on delete set null,
  decision_id uuid references public.ac_whatsapp_ri_decisions(id) on delete set null,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

alter table public.ac_whatsapp_conversations
  add column if not exists automation_paused boolean not null default false,
  add column if not exists automation_mode text not null default 'manual',
  add column if not exists automation_doctrine_pack_id uuid references public.ac_whatsapp_ri_doctrine_packs(id) on delete set null,
  add column if not exists automation_goal text,
  add column if not exists automation_excluded boolean not null default false,
  add column if not exists automation_maturity_level text,
  add column if not exists automation_last_decision_at timestamptz;

alter table public.ac_whatsapp_campaigns
  add column if not exists automation_doctrine_pack_id uuid references public.ac_whatsapp_ri_doctrine_packs(id) on delete set null,
  add column if not exists automation_goal text;

create index if not exists ac_whatsapp_ri_relationship_memory_contact_idx on public.ac_whatsapp_ri_relationship_memory(contact_id,updated_at desc);
create index if not exists ac_whatsapp_ri_nodes_pack_status_idx on public.ac_whatsapp_ri_doctrine_nodes(pack_id,status,priority desc);
create index if not exists ac_whatsapp_ri_nodes_customer_service_idx on public.ac_whatsapp_ri_doctrine_nodes(customer_type,service_line,journey_stage,intent_family);
create index if not exists ac_whatsapp_ri_decisions_conversation_idx on public.ac_whatsapp_ri_decisions(conversation_id,created_at desc);
create index if not exists ac_whatsapp_ri_learning_conversation_idx on public.ac_whatsapp_ri_learning_events(conversation_id,created_at desc);
create index if not exists ac_whatsapp_ri_runtime_created_idx on public.ac_whatsapp_ri_runtime_events(created_at desc);
create index if not exists ac_whatsapp_ri_import_rows_status_idx on public.ac_whatsapp_ri_import_rows(import_id,status);

alter table public.ac_whatsapp_ri_doctrine_packs enable row level security;
alter table public.ac_whatsapp_ri_doctrine_nodes enable row level security;
alter table public.ac_whatsapp_ri_engine_settings enable row level security;
alter table public.ac_whatsapp_ri_imports enable row level security;
alter table public.ac_whatsapp_ri_import_rows enable row level security;
alter table public.ac_whatsapp_ri_conversation_state enable row level security;
alter table public.ac_whatsapp_ri_relationship_memory enable row level security;
alter table public.ac_whatsapp_ri_decisions enable row level security;
alter table public.ac_whatsapp_ri_learning_events enable row level security;
alter table public.ac_whatsapp_ri_maturity enable row level security;
alter table public.ac_whatsapp_ri_governance_proposals enable row level security;
alter table public.ac_whatsapp_ri_simulations enable row level security;
alter table public.ac_whatsapp_ri_runtime_events enable row level security;

-- Service-role API is the only intended access path. No broad anon/authenticated policies are created.

insert into public.ac_whatsapp_ri_engine_settings(scope_type,scope_id,autonomy_mode,enabled,min_autonomy_confidence,min_assist_confidence,commercial_intensity_cap,after_hours_start,after_hours_end,timezone,overflow_threshold)
select 'global',null,'manual',true,.82,.55,5,'19:00','08:00','Africa/Casablanca',25
where not exists(select 1 from public.ac_whatsapp_ri_engine_settings where scope_type='global' and scope_id is null);

insert into public.ac_whatsapp_ri_doctrine_packs(code,name,description,service_line,customer_type,status,maturity_level,version,source_kind,applicability_score,coverage_score,commercial_priority,default_goal)
values('SOVEREIGN_CORE_SALES','Sovereign Core Sales & Relationship','Foundational commercial cognition: qualification, trust, objection, closing, recovery, lifecycle progression and governed handoff.','all','all','active','L2',1,'system',92,88,100,'advance_commercial_journey')
on conflict(code) do nothing;

with pack as (select id from public.ac_whatsapp_ri_doctrine_packs where code='SOVEREIGN_CORE_SALES')
insert into public.ac_whatsapp_ri_doctrine_nodes(pack_id,code,title,customer_type,service_line,journey_stage,intent_family,trigger_terms,objective,tone_profile,commercial_intensity,action_type,response_guidance,qualification_questions,objection_class,success_signals,failure_signals,priority,maturity_weight,status)
select pack.id, v.code,v.title,v.customer_type,v.service_line,v.journey_stage,v.intent_family,v.trigger_terms,v.objective,v.tone_profile::jsonb,v.commercial_intensity,v.action_type,v.response_guidance,v.qualification_questions,v.objection_class,v.success_signals,v.failure_signals,v.priority,v.maturity_weight,'active'
from pack cross join (values
 ('CORE_FIRST_CONTACT','First contact · understand before selling','all','all','aware','first_contact',array['bonjour','hello','information','interesse','intéressé'],'qualify_need','{"primary":"warm_commercial"}',2,'qualify','Merci pour votre message. Pour vous orienter vers la solution AngelCare la plus pertinente, je vais d’abord comprendre précisément votre besoin.',array['Quel est votre besoin prioritaire aujourd’hui ?'],null,array['need_explained','service_identified'],array['no_context'],90,.35),
 ('CORE_B2B_DISCOVERY','B2B · business discovery','b2b','all','curious','discovery',array['creche','crèche','ecole','école','entreprise','partenariat','solution'],'discover_business_pain','{"primary":"b2b_executive"}',3,'qualify','Votre contexte peut avoir un potentiel plus large qu’une simple demande d’information. Je veux surtout comprendre ce que vous cherchez à améliorer concrètement dans votre établissement.',array['Quel est aujourd’hui le point qui vous fait perdre le plus de temps, de contrôle ou de satisfaction client ?','Qui sera impliqué dans la décision si nous identifions une solution pertinente ?'],null,array['pain_identified','stakeholder_identified'],array['generic_interest_only'],100,.45),
 ('CORE_B2C_DISCOVERY','B2C · family need discovery','b2c','home_childcare','curious','discovery',array['garde','enfant','maman','mother','nounou','domicile'],'qualify_family_need','{"primary":"warm_care_commercial"}',2,'qualify','Je vais vous aider à identifier la formule la plus adaptée sans vous faire perdre du temps. Quelques précisions suffisent pour cadrer correctement le besoin.',array['Quel âge a votre enfant et à quels jours ou horaires avez-vous besoin d’aide ?','Dans quelle ville ou zone se situe le domicile ?'],null,array['schedule_known','location_known','child_age_known'],array['missing_eligibility'],100,.45),
 ('CORE_INFORMATION_TO_OPPORTUNITY','Information request → commercial opening','all','all','engaged','information_request',array['catalogue','brochure','presentation','présentation','pdf','document'],'convert_information_request_to_discovery','{"primary":"warm_commercial"}',3,'qualify','Bien sûr. Je peux vous orienter vers le support le plus pertinent. Avant de vous envoyer trop d’informations, dites-moi simplement ce que vous souhaitez résoudre ou comparer en priorité.',array['Quel résultat aimeriez-vous obtenir concrètement ?'],null,array['specific_interest_identified'],array['document_only_dead_end'],95,.4),
 ('CORE_PRICING','Price inquiry · protect value before commodity comparison','all','all','engaged','pricing',array['prix','tarif','combien','budget','devis'],'build_value_before_price','{"primary":"commercial_clear"}',4,'qualify','Je peux vous donner une orientation tarifaire fiable, mais le bon montant dépend surtout du besoin, du volume et du niveau de service. Je préfère vous éviter un chiffre trompeur.',array['Pouvez-vous me préciser le besoin, la fréquence ou le volume concerné ?'],'price',array['scope_defined','quote_ready'],array['price_only_exit'],95,.5),
 ('CORE_TRUST','Trust objection · evidence first','all','all','objection','trust',array['confiance','fiable','securite','sécurité','experience','expérience','garantie'],'build_trust_with_evidence','{"primary":"reassuring"}',2,'reply','Votre vigilance est légitime. Je vais rester précis sur ce que nous pouvons réellement garantir et sur les éléments vérifiables avant toute décision.',array['Quel point vous rassurerait le plus avant d’avancer ?'],'trust',array['trust_concern_resolved'],array['unresolved_trust'],90,.45),
 ('CORE_OBJECTION','General objection · clarify hidden cause','all','all','objection','all',array['cher','reflechir','réfléchir','pas maintenant','comparer','déjà','deja'],'clarify_real_objection','{"primary":"commercial_consultative"}',3,'qualify','Je comprends. Avant de vous relancer inutilement, je préfère identifier le vrai point de blocage afin de voir si nous pouvons réellement créer de la valeur.',array['Le principal frein est-il le budget, le timing, la confiance, l’organisation interne ou l’adéquation de la solution ?'],'general',array['objection_classified'],array['objection_unresolved'],85,.45),
 ('CORE_CLOSE','High intent · secure next commitment','all','all','closing','closing_signal',array['commencer','rendez-vous','meeting','contrat','signer','devis','disponible'],'secure_next_commitment','{"primary":"commercial_closer"}',5,'close','Très bien. Nous avons assez d’éléments pour passer à une prochaine étape concrète plutôt que rester dans une discussion générale.',array['Préférez-vous avancer par un échange court de qualification ou directement par une proposition structurée ?'],null,array['meeting_booked','proposal_requested','commitment_captured'],array['decision_stalled'],100,.55),
 ('CORE_COMPLAINT_RECOVERY','Complaint · recover relationship before sale','all','all','recovery','complaint_recovery',array['probleme','problème','mecontent','mécontent','decu','déçu','plainte','retard','inacceptable'],'recover_relationship','{"primary":"reassuring"}',0,'protect','Je comprends que la priorité ici est de résoudre correctement la situation avant toute autre discussion commerciale. Je vais d’abord clarifier ce qui s’est passé et la prochaine action utile.',array['Quel est le point précis que vous souhaitez voir corrigé en priorité ?'],null,array['issue_clarified','relationship_stabilized'],array['complaint_escalated'],100,.5),
 ('CORE_SPECIAL_CARE','Special-care inquiry · careful qualification','b2c','special_childcare','all','special_care',array['autisme','autism','besoins spéciaux','besoins speciaux','handicap','trisomie'],'safe_special_care_qualification','{"primary":"reassuring"}',1,'qualify','Merci pour ces précisions. Pour ce type de besoin, nous devons rester très rigoureux sur l’adéquation du service et ne pas faire de promesse sans qualification suffisante.',array['Pouvez-vous me préciser les besoins d’accompagnement quotidiens et les consignes déjà établies par la famille ou les professionnels qui suivent l’enfant ?'],null,array['care_requirements_known'],array['medical_claim_required'],100,.6),
 ('CORE_POSTPARTUM','Postpartum · reduce cognitive load','b2c','postpartum','all','postpartum',array['postpartum','après accouchement','apres accouchement','nouveau-né','nouveau ne','newborn'],'gentle_postpartum_qualification','{"primary":"reassuring"}',1,'qualify','Merci pour votre confiance. Nous allons faire simple et pratique : comprendre l’aide dont vous avez besoin, le rythme souhaité et ce qui vous soulagerait réellement au quotidien.',array['Quel type d’aide vous serait le plus utile et à partir de quelle date ?'],null,array['support_need_known'],array['medical_request'],100,.6),
 ('CORE_FOLLOWUP','No response · adaptive follow-up','all','all','engaged','short_reply',array['ok','d accord','d’accord','merci'],'preserve_momentum','{"primary":"warm_commercial"}',2,'followup','Parfait. Je garde le fil clair et je peux vous aider à passer à la prochaine étape dès que vous êtes prêt(e).',array[]::text[],null,array['conversation_continues'],array['stalled'],70,.3),
 ('CORE_HANDOFF','High-risk / unsupported · human escalation','all','all','all','all',array['urgence médicale','danger','avocat','police','diagnostic','medicament'],'human_handoff','{"primary":"reassuring"}',0,'handoff',null,array[]::text[],null,array['handoff_completed'],array['unsafe_autonomy'],100,.8)
) as v(code,title,customer_type,service_line,journey_stage,intent_family,trigger_terms,objective,tone_profile,commercial_intensity,action_type,response_guidance,qualification_questions,objection_class,success_signals,failure_signals,priority,maturity_weight)
on conflict(pack_id,code) do nothing;


with pack as (select id from public.ac_whatsapp_ri_doctrine_packs where code='SOVEREIGN_CORE_SALES')
insert into public.ac_whatsapp_ri_doctrine_nodes(pack_id,code,title,customer_type,service_line,journey_stage,intent_family,trigger_terms,objective,tone_profile,commercial_intensity,action_type,response_guidance,qualification_questions,objection_class,success_signals,failure_signals,priority,maturity_weight,status)
select pack.id, v.code,v.title,v.customer_type,v.service_line,v.journey_stage,v.intent_family,v.trigger_terms,v.objective,v.tone_profile::jsonb,v.commercial_intensity,v.action_type,v.response_guidance,v.qualification_questions,v.objection_class,v.success_signals,v.failure_signals,v.priority,v.maturity_weight,'active'
from pack cross join (values
 ('CORE_OUTBOUND_B2B','Outbound B2B · relevance opening','b2b','all','aware','outbound_prospecting',array['outbound','prospecting','campaign'],'create_relevance_and_permission','{"primary":"b2b_executive"}',3,'reply','Bonjour {{first_name}}. Je vous contacte avec une raison précise liée à votre activité : plutôt que vous envoyer une présentation générique, je préfère vérifier en une question si le sujet peut réellement être utile pour votre établissement.',array['Aujourd’hui, quel sujet est le plus prioritaire pour votre établissement : organisation, expérience parent, acquisition, communication ou développement ?'],null,array['reply_received','business_pain_identified'],array['no_interest','opt_out'],100,.55),
 ('CORE_REACTIVATION','Dormant relationship reactivation','all','all','engaged','reactivation',array['reactivation','dormant','ancienne demande'],'reopen_with_new_value','{"primary":"warm_commercial"}',3,'followup','Je reviens vers vous avec une raison utile plutôt qu’une relance générique. Votre précédent besoin reste pertinent et nous pouvons reprendre exactement là où l’échange s’était arrêté.',array['Est-ce toujours un sujet d’actualité ou votre priorité a-t-elle changé ?'],null,array['relationship_reopened'],array['still_dormant'],85,.45),
 ('CORE_UPSELL','Customer expansion · relevant value only','all','all','expansion','all',array['client','service actif','existing customer'],'identify_relevant_expansion','{"primary":"commercial_consultative"}',3,'qualify','Puisque le service principal est déjà en place, le bon sujet n’est pas de vous vendre davantage au hasard, mais d’identifier s’il existe un besoin adjacent qui améliorerait réellement votre expérience.',array['Y a-t-il aujourd’hui un besoin complémentaire ou une friction qui reste non couverte ?'],null,array['expansion_need_identified'],array['irrelevant_upsell'],80,.5),
 ('CORE_RENEWAL','Renewal protection','all','all','renewal','all',array['renouvellement','renewal','expiration','expiry'],'secure_renewal_and_value','{"primary":"commercial_consultative"}',3,'close','Avant le renouvellement, je veux vérifier que la valeur perçue reste claire et qu’aucun point d’insatisfaction ne doit être traité avant d’avancer.',array['Qu’aimeriez-vous absolument conserver ou améliorer pour la prochaine période ?'],null,array['renewal_intent'],array['renewal_risk'],90,.55),
 ('CORE_REFERRAL','Referral after positive outcome','all','all','referral','all',array['satisfait','satisfaite','excellent','parfait','merci beaucoup'],'ask_for_referral_at_right_moment','{"primary":"warm_commercial"}',2,'reply','Je suis ravi que l’expérience soit positive. Si vous connaissez une personne ou une organisation pour qui ce type de service serait réellement utile, je peux lui donner le même niveau d’accompagnement sans engagement.',array[]::text[],null,array['referral_received'],array['bad_timing'],70,.35),
 ('CORE_STALLED','Stalled opportunity · change angle','all','all','evaluating','all',array['silence','stalled','no response'],'restore_momentum_without_pressure','{"primary":"warm_commercial"}',2,'followup','Je ne veux pas multiplier les relances. Je vous laisse simplement un point utile pour décider : si le besoin existe toujours, nous pouvons reprendre en une seule étape claire ; sinon je clôture proprement le suivi.',array['Souhaitez-vous que je garde le dossier ouvert ou que je le mette en pause ?'],null,array['status_clarified'],array['unwanted_followup'],80,.45),
 ('CORE_COMPETITOR','Competitive evaluation','all','all','evaluating','all',array['concurrent','concurrence','compare','comparaison','autre solution'],'differentiate_on_fit_not_attack','{"primary":"commercial_clear"}',4,'qualify','Comparer plusieurs options est logique. Le plus utile est de comparer sur les critères qui auront un impact réel pour vous, pas uniquement sur une liste de fonctionnalités ou un prix isolé.',array['Quels sont les deux ou trois critères qui feront réellement la différence dans votre décision ?'],'competition',array['decision_criteria_known'],array['competitor_attack'],90,.5),
 ('CORE_SMART_SILENCE','Smart silence / timing protection','all','all','all','all',array['pas maintenant','plus tard','je reviens','busy','occupé'],'respect_timing_and_schedule','{"primary":"warm_commercial"}',0,'wait','Je comprends. Je respecte votre timing et je garde le contexte pour éviter de vous faire répéter les mêmes informations lorsque nous reprendrons.',array['Quel moment serait le plus pertinent pour reprendre ?'],null,array['followup_time_known'],array['over_contact'],100,.65)
) as v(code,title,customer_type,service_line,journey_stage,intent_family,trigger_terms,objective,tone_profile,commercial_intensity,action_type,response_guidance,qualification_questions,objection_class,success_signals,failure_signals,priority,maturity_weight)
on conflict(pack_id,code) do nothing;


