with pack as (select id from public.ac_whatsapp_ri_doctrine_packs where code='SOVEREIGN_CORE_SALES')
insert into public.ac_whatsapp_ri_doctrine_nodes(
  pack_id,code,title,customer_type,service_line,journey_stage,intent_family,trigger_terms,
  objective,tone_profile,commercial_intensity,action_type,response_guidance,
  qualification_questions,objection_class,proof_options,forbidden_claims,
  success_signals,failure_signals,priority,maturity_weight,status
)
select pack.id,v.code,v.title,v.customer_type,v.service_line,v.journey_stage,v.intent_family,v.trigger_terms,
       v.objective,jsonb_build_object('primary',v.tone),v.commercial_intensity,v.action_type,v.response_guidance,
       v.qualification_questions,v.objection_class,v.proof_options,v.forbidden_claims,
       v.success_signals,v.failure_signals,v.priority,v.maturity_weight,'active'
